// textNode.js — Part 3: auto-resize + dynamic {{ variable }} handles
import { useState, useEffect, useRef } from 'react';
import { Handle, Position } from 'reactflow';
import { BaseNode } from './BaseNode';

const VARIABLE_REGEX = /\{\{\s*([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\}\}/g;

const extractVariables = (text) => {
  const vars = [];
  const seen = new Set();
  let match;
  const regex = new RegExp(VARIABLE_REGEX.source, 'g');
  while ((match = regex.exec(text)) !== null) {
    if (!seen.has(match[1])) {
      seen.add(match[1]);
      vars.push(match[1]);
    }
  }
  return vars;
};

const MIN_WIDTH = 220;
const MIN_HEIGHT = 80;
const CHAR_WIDTH = 8;
const LINE_HEIGHT = 20;
const PADDING = 40;

export const TextNode = ({ id, data }) => {
  const [currText, setCurrText] = useState(data?.text || '{{input}}');
  const [variables, setVariables] = useState([]);
  const [nodeSize, setNodeSize] = useState({ width: MIN_WIDTH, height: MIN_HEIGHT });
  const textareaRef = useRef(null);

  useEffect(() => {
    const vars = extractVariables(currText);
    setVariables(vars);

    // Calculate node size based on text content
    const lines = currText.split('\n');
    const longestLine = Math.max(...lines.map(l => l.length), 10);
    const newWidth = Math.max(MIN_WIDTH, longestLine * CHAR_WIDTH + PADDING);
    const newHeight = Math.max(MIN_HEIGHT, lines.length * LINE_HEIGHT + 80 + vars.length * 24);
    setNodeSize({ width: newWidth, height: newHeight });
  }, [currText]);

  return (
    <div
      className="base-node"
      style={{ width: nodeSize.width, minHeight: nodeSize.height, '--node-accent': '#ec4899', position: 'relative' }}
    >
      {/* Dynamic variable input handles */}
      {variables.map((varName, i) => (
        <Handle
          key={varName}
          type="target"
          position={Position.Left}
          id={`${id}-${varName}`}
          style={{ top: `${((i + 1) / (variables.length + 1)) * 100}%` }}
          className="node-handle node-handle--input"
        >
          <span className="handle-label handle-label--left">{varName}</span>
        </Handle>
      ))}

      {/* Header */}
      <div className="node-header" style={{ background: '#ec4899' }}>
        <span className="node-icon">📝</span>
        <span className="node-title">Text</span>
      </div>

      {/* Body */}
      <div className="node-body">
        <div className="node-field">
          <label className="node-label">Content</label>
          <textarea
            ref={textareaRef}
            className="node-textarea"
            value={currText}
            onChange={(e) => setCurrText(e.target.value)}
            style={{ width: '100%', minHeight: Math.max(60, nodeSize.height - 90) }}
            placeholder="Type text... use {{variable}} to add inputs"
          />
        </div>
        {variables.length > 0 && (
          <div className="node-vars">
            {variables.map(v => (
              <span key={v} className="node-var-tag">{'{'}{'{' + v}{'}'}'}'</span>
            ))}
          </div>
        )}
      </div>

      {/* Output handle */}
      <Handle
        type="source"
        position={Position.Right}
        id={`${id}-output`}
        style={{ top: '50%' }}
        className="node-handle node-handle--output"
      />
    </div>
  );
};
